import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.BvlN9b-o.js";const u=JSON.parse('{"title":"Build your ticket SaaS backend","description":"","frontmatter":{"docLocale":"en","counterpart":"/learn/","contentType":"overview","prev":{"text":"Developer documentation","link":"/en/docs/"},"next":{"text":"01 Module and HTTP endpoint","link":"/en/learn/module"}},"headers":[],"relativePath":"en/learn/index.md","filePath":"en/learn/index.md"}'),n={name:"en/learn/index.md"};function o(r,e,d,c,p,l){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="build-your-ticket-saas-backend" tabindex="-1">Build your ticket SaaS backend <a class="header-anchor" href="#build-your-ticket-saas-backend" aria-label="Permalink to &quot;Build your ticket SaaS backend&quot;">​</a></h1><p>Start with one Rust HTTP endpoint and evolve the same ticket module through persistence, identity, authorization, transactions, files, background tasks, testing and deployment. The course uses backend interfaces and requires no frontend implementation.</p><p>Tickets are reader-added course code; the default app retains the knowledge reference business. Each deployment serves one Organization, and tickets do not create another tenant. The course policy allows the creator and current Owner/Admin to access a ticket while hiding it from other members.</p><h2 id="prerequisites-and-sequence" tabindex="-1">Prerequisites and sequence <a class="header-anchor" href="#prerequisites-and-sequence" aria-label="Permalink to &quot;Prerequisites and sequence&quot;">​</a></h2><p>Complete <a href="./../getting-started/quickstart">backend quick start</a> and prepare the repository&#39;s pinned Rust, Node, pnpm, just and Docker. Run from the original template root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TEMPLATE_ROOT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COURSE_ROOT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TEMPLATE_ROOT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.scratch/ticket-saas&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/tutorial-course.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --stage</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> module</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$COURSE_ROOT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>The course tool wires code into this independent template copy without registering it in the original default app. It assigns a separate Compose project, volumes and free ports, recording public request addresses in <code>.course.env</code>; later checkpoints preserve them. Stop the copy&#39;s development processes before advancing, run the command in the original template, then run the copy. Save your own edits first; checkpoint installation is not a merge tool.</p><table tabindex="0"><thead><tr><th>Lesson</th><th>Development goal</th><th>Code checkpoint</th></tr></thead><tbody><tr><td><a href="./module">01</a></td><td>Module, Router and OpenAPI</td><td><code>module</code></td></tr><tr><td><a href="./migrations">02</a></td><td>Owned schema/migration and the first real write</td><td><code>crud</code></td></tr><tr><td><a href="./protocol">03</a></td><td>Protocols, validation and public errors</td><td>Keep <code>crud</code></td></tr><tr><td><a href="./authorization">04</a></td><td>Session, active Membership and ticket policy</td><td>Keep <code>crud</code></td></tr><tr><td><a href="./transactions">05</a></td><td>Business and Audit commit together</td><td>Keep <code>crud</code></td></tr><tr><td><a href="./retries-versions">06</a></td><td>Idempotency and concurrent versions</td><td>Keep <code>crud</code></td></tr><tr><td><a href="./files">07</a></td><td>Upload, verification, publication and download</td><td><code>files</code></td></tr><tr><td><a href="./jobs">08</a></td><td>JSON snapshot export, Worker and notifications</td><td><code>jobs</code></td></tr><tr><td><a href="./verification">09</a></td><td>HTTP checks and generated SDK</td><td>Keep <code>jobs</code></td></tr><tr><td><a href="./production">10</a></td><td>Deployment, observation, backup and restore</td><td>Keep <code>jobs</code></td></tr></tbody></table><p>Four checkpoints provide complete runnable code. Lessons 03–06 verify individual responsibilities in one protected CRUD implementation rather than running an unprotected intermediate business. Full source lives in <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/examples/tutorial-tickets" target="_blank" rel="noreferrer">examples/tutorial-tickets</a>; excerpts share that implementation so you do not have to invent missing helpers.</p><h2 id="business-contract" tabindex="-1">Business contract <a class="header-anchor" href="#business-contract" aria-label="Permalink to &quot;Business contract&quot;">​</a></h2><p>A Ticket has title, description, <code>open | closed</code> status and an integer version. Creation uses Idempotency-Key; updates carry the expected version. Resource authorization precedes reads, replay and publication.</p><p>Attachments belong to tickets while Core Files owns object state. Export produces JSON up to 64 KiB with request-time ticket and attachment metadata, not attachment bytes or a ZIP. Business retention is one hour. Downloads and Worker publication recheck identity, Membership and resource access; an invalid initiating Session cannot publish.</p><p>These are course business decisions, not automatic Core ticket rules. Actual Rust/OpenAPI defines protocols and calls. Chapter validation commands must be executed separately; footer SHA identifies build source only.</p><p>Next: <a href="./module">Add the first ticket endpoint</a>.</p><hr><p>Source version：<code>261be5bb90df</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/learn/index.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,16)])])}const k=t(n,[["render",o]]);export{u as __pageData,k as default};
